use std::{io::{Read, Write}, net::{TcpListener, TcpStream}, thread};

#[derive(Clone, Copy)]
struct Faculty { id: &'static str, name: &'static str, short: &'static str, description: &'static str, color: &'static str, programs: &'static str }
#[derive(Clone, Copy)]
struct Course { id: &'static str, title: &'static str, desc: &'static str, teacher: &'static str, level: &'static str, language: &'static str, year: u8, term: u8, faculties: &'static [&'static str], tag: &'static str }
