fn respond(mut stream: TcpStream) -> std::io::Result<()> { stream.set_read_timeout(Some(std::time::Duration::from_secs(5)))?; let mut buffer=[0;8192]; let n=stream.read(&mut buffer)?; let request=String::from_utf8_lossy(&buffer[..n]); let mut parts=request.lines().next().unwrap_or("").split_whitespace(); let method=parts.next().unwrap_or(""); let target=parts.next().unwrap_or("/"); let path=target.split('?').next().unwrap_or("/"); let (status,mime,body)=if method!="GET" && method!="HEAD" {(405,"text/plain; charset=utf-8","Method not allowed".to_owned())} else {match path {"/static/style.css"=>(200,"text/css; charset=utf-8",include_str!("../static/style.css").to_owned()),"/static/app.js"=>(200,"text/javascript; charset=utf-8",include_str!("../static/app.js").to_owned()),_=>{let(s,b)=page(path);(s,"text/html; charset=utf-8",b)}}}; let reason=match status {200=>"OK",404=>"Not Found",_=>"Method Not Allowed"}; write!(stream,"HTTP/1.1 {} {}\r\nContent-Type: {}\r\nContent-Length: {}\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n\r\n",status,reason,mime,body.len())?; if method!="HEAD" {stream.write_all(body.as_bytes())?;} Ok(()) }
fn main()->std::io::Result<()> { let address=std::env::var("AMIGO_BIND").unwrap_or_else(|_|"127.0.0.1:3000".into()); let listener=TcpListener::bind(&address)?; eprintln!("Amigo listening on http://{}",address); for connection in listener.incoming() { match connection {Ok(stream)=>{thread::spawn(move||{if let Err(e)=respond(stream){eprintln!("request error: {e}");}});},Err(e)=>eprintln!("connection error: {e}")}} Ok(()) }
#[cfg(test)] mod tests { use super::*; #[test] fn shared_courses_are_single_records_linked_to_multiple_faculties(){assert_eq!(COURSES.iter().filter(|c|c.id=="entrepreneurship").count(),1);let c=course("entrepreneurship").unwrap();assert!(shared(c));assert!(c.faculties.contains(&"business"));assert!(c.faculties.contains(&"engineering"));assert!(!c.faculties.contains(&"pharmacy"));} #[test] fn all_links_resolve_and_ids_are_unique(){for (i,c) in COURSES.iter().enumerate(){assert!(c.faculties.iter().all(|id|faculty(id).is_some()));assert!(!COURSES[..i].iter().any(|other|other.id==c.id));assert_eq!(page(&format!("/courses/{}",c.id)).0,200);}for f in FACULTIES {assert_eq!(page(&format!("/faculties/{}",f.id)).0,200);}} #[test] fn unknown_pages_return_404(){assert_eq!(page("/courses/missing").0,404);assert_eq!(page("/faculties/missing").0,404);} }
